with raw_totals as (select count(*) as rows, sum("impressions"::numeric) as impressions, sum("clicks"::numeric) as clicks, sum("conversions"::numeric) as conversions, sum("ad_spend"::numeric) as ad_spend, sum("revenue"::numeric) as revenue from {{ source('raw', 'global_ads_performance') }}), fact_totals as (select count(*) as rows, sum("Impressions") as impressions, sum("Clicks") as clicks, sum("Conversions") as conversions, sum("AdSpend") as ad_spend, sum("Revenue") as revenue from {{ ref('fct_ad_performance') }})
select r.*, f.* from raw_totals r cross join fact_totals f
where r.rows is distinct from f.rows or r.impressions is distinct from f.impressions or r.clicks is distinct from f.clicks or r.conversions is distinct from f.conversions or r.ad_spend is distinct from f.ad_spend or r.revenue is distinct from f.revenue
